.wp-home .newsletter-form:not(.wp-app, .wp-app *) {
    display: flex;
    max-width: 450px;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    overflow: hidden;
    background: #fff;
}
.wp-home .newsletter-form input[type="email"]:not(.wp-app, .wp-app *) {
    flex: 1;
    padding: 12px 15px;
    border: none;
    outline: none;
    font-size: 14px;
    color: #333;
}
.wp-home .newsletter-form input[type="email"]:not(.wp-app, .wp-app *)::placeholder {
    color: #999;
}
.wp-home .newsletter-form button:not(.wp-app, .wp-app *) {
    background: #DD2E44;
    color: #fff;
    border: none;
    padding: 12px 25px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.3s ease;
}
.wp-home .newsletter-form button:hover:not(.wp-app, .wp-app *) {
    background: #d43f4f;
}
.wp-home .newsletter-message:not(.wp-app, .wp-app *) {
    margin-top: 10px;
    font-size: 14px;
}
.wp-home .newsletter-message.success:not(.wp-app, .wp-app *) { color: green; }
.wp-home .newsletter-message.error:not(.wp-app, .wp-app *) { color: red; }
